// Extrahiere den vollstaendigen build_escalation()-Text aus dem Webhook-Payload
const payload = $input.first().json.body || $input.first().json;

const task = payload.task || 'Unbekannte Aufgabe';
const status = payload.status || 'ESCALATED';
const rounds = payload.round || '?';
const escalationText = payload.escalation_text || '';
const timestamp = payload.timestamp || new Date().toISOString();

let message = '';
if (escalationText) {
  message = `🚨 *Gate-A2 Eskalation* (Runde ${rounds})\n\n${escalationText}`;
} else {
  message = `🚨 *Gate-A2 Eskalation* (Runde ${rounds})\n\n*Aufgabe:* ${task}\n*Status:* ${status}\n*Zeitstempel:* ${timestamp}\n\nBitte pruefe die Datei \`a2-eskalation.md\` oder Open WebUI zur Diagnose.`;
}

// Telegram-Zeichenlimit sicherstellen (max 4096 Zeichen)
if (message.length > 4000) {
  message = message.substring(0, 3950) + '\n\n... [Nachricht gekuerzt, siehe a2-eskalation.md]';
}

return [
  {
    json: {
      text: message,
      task: task,
      status: status,
      round: rounds
    }
  }
];
